9	export function useNow(active, ms = 1000) {
10	  const [now, setNow] = React.useState(Date.now());
11	  React.useEffect(() => {
12	    if (!active) return;
13	    const t = setInterval(() => setNow(Date.now()), ms);
14	    return () => clearInterval(t);
15	  }, [active, ms]);
16	  return now;
17	}
