19	export function useStickyScroll(dep) {
20	  const ref = React.useRef(null);
21	  const stick = React.useRef(true);
22	  const [away, setAway] = React.useState(false);
23	  React.useLayoutEffect(() => {
24	    if (ref.current && stick.current) ref.current.scrollTop = ref.current.scrollHeight;
25	  }, [dep]);
26	  const onScroll = (e) => {
27	    const el = e.currentTarget;
28	    stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 32;
29	    setAway(!stick.current);
30	  };
31	  const jump = () => {
32	    stick.current = true;
33	    setAway(false);
34	    if (ref.current) ref.current.scrollTo({ top: ref.current.scrollHeight, behavior: "smooth" });
35	  };
36	  return { ref, onScroll, away, jump };
37	}
