54	function parseLine(entry) {
55	  const raw = entry.line || "";
56	  const time = raw.match(/^\[(\d{2}:\d{2}:\d{2})/)?.[1] || clock(entry.at);
57	  let text = raw.replace(/^(\[[^\]]*\]\s*)+:?\s*/, "");
58	  let source = "server";
59	  const prefix = raw.match(/^\[(bot|chat|benana)\]\s*/);
60	  if (prefix) {
61	    source = prefix[1];
62	    text = raw.slice(prefix[0].length);
63	  }
64	  const plugin = text.match(/^\[([A-Za-z0-9_]+)\]\s*/);
65	  if (plugin) text = text.slice(plugin[0].length);
66	  return { time, text: text || raw, source, plugin: plugin?.[1] || null, level: entry.level || "info" };
67	}
