74	  React.useEffect(() => {
75	    let live = true;
76	    call("game:logs", { limit: 200 })
77	      .then((backlog) => live && setLines((prev) => [...backlog.map(stamp), ...prev].slice(-500)))
78	      .catch(() => {});
79	    const offs = [
80	      on("game:log", (l) => setLines((prev) => [...prev.slice(-499), stamp(l)])),
81	      on("game:action", (a) => {
82	        if (!a.done) return;
83	        const text = a.error ? `${a.tool} failed: ${a.error}` : `${a.tool} ${JSON.stringify(a.args || {}).slice(0, 90)}`;
84	        setLines((prev) => [
85	          ...prev.slice(-499),
86	          { time: clock(a.done), text, source: "bot", plugin: null, level: a.error ? "error" : "info", key: ++seq.current },
87	        ]);
88	      }),
89	    ];
90	    return () => {
91	      live = false;
92	      offs.forEach((off) => off());
93	    };
94	  }, []);
95	
96	  const errors = lines.filter((l) => l.level === "error").length;
97	  const warns = lines.filter((l) => l.level === "warn").length;
98	  const { ref, onScroll, away, jump } = useStickyScroll(lines.length);
99	  const modName = mod?.name;
