157	  const timers = React.useRef({});
158	  const clearTimers = () => {
159	    Object.values(timers.current).forEach(clearTimeout);
160	    timers.current = {};
161	  };
162	  React.useEffect(() => clearTimers, []);
163	
164	  React.useEffect(() => {
165	    clearTimers();
166	    setEvidence({});
167	    pending.current = new Set();
168	  }, [mod?.id]);
