260	    if (f.kind === "session") return;
261	    if (f.role === "benana") {
262	      turn = null;
263	      if (f.kind === "phase") items.push({ type: "phase", key, f });
264	      else if (f.kind === "failure" || f.kind === "error") items.push({ type: "alert", key, f });
265	      else items.push({ type: "note", key, f });
266	      return;
267	    }
268	    if (f.kind === "plan") {
269	      items.push({ type: "testplan", key, bare: turn?.role === "spec" });
270	      turn = null;
271	      return;
272	    }
273	    const id = `${f.role}:${f.attempt || 0}`;
274	    if (!turn || turn.id !== id) {
275	      turn = { type: "turn", key, id, role: f.role, attempt: f.attempt || null, entries: [] };
276	      items.push(turn);
277	    }
278	    turn.entries.push(f);
279	  });
280	  if (!feed.some((f) => f.kind === "plan") && mod.testPlan) items.splice(2, 0, { type: "testplan", key: "tp" });
281	  if (!mod.running && ["passed", "failed", "stopped"].includes(mod.status)) items.push({ type: "result", key: "result" });
