642	function inline(text) {
643	  return text.split(/(\*\*[^*]+\*\*|`[^`]+`)/g).map((part, i) =>
644	    part.startsWith("**") && part.endsWith("**") && part.length > 4 ? (
645	      <strong key={i}>{part.slice(2, -2)}</strong>
646	    ) : part.startsWith("`") && part.endsWith("`") && part.length > 2 ? (
647	      <code key={i}>{part.slice(1, -1)}</code>
648	    ) : (
649	      part
650	    ),
651	  );
652	}
