154	async function runTool(tool, args = {}) {
155	  if (BOT_TOOLS.has(tool)) return botCall(tool, args);
156	  if (tool === 'game_setup') {
157	    const out = [];
158	    const { position } = await botCall('bot_state');
159	    if (Math.hypot(position[0] - ARENA[0], position[2] - ARENA[2]) > 8) {
