161	      await botCall('wait_ticks', { ticks: 5 });
162	      out.push({ command: 'tp back to the arena center', output: 'Benana keeps the bot in camera view' });
163	    }
164	    for (const raw of args.commands || []) {
165	      const cmd = String(raw).replace(/^\//, '').replaceAll('@bot', BOT);
166	      out.push({ command: cmd, output: await server.command(`execute as ${BOT} at ${BOT} run ${cmd}`) });
167	    }
168	    return out;
169	  }
170	  if (tool === 'reset_arena') {
171	    await resetArena();
172	    await prepareBot();
173	    await botCall('wait_ticks', { ticks: 10 });
174	    return { reset: true, note: 'Arena rebuilt flat (grass at y=64), all mobs/items/projectiles removed, bot back at the center with an empty inventory. Run your setup commands again. Plugin state such as cooldowns is NOT reset; wait it out.' };
175	  }
