180	function startControl() {
181	  if (control) return Promise.resolve();
182	  return new Promise((resolve) => {
183	    control = http.createServer((req, res) => {
184	      const match = req.method === 'POST' && req.url.match(/^\/tool\/(\w+)$/);
185	      if (!match) { res.writeHead(404).end(); return; }
186	      let body = '';
187	      req.on('data', (d) => { body += d; });
188	      req.on('end', async () => {
189	        let args = {};
190	        try { args = body ? JSON.parse(body) : {}; } catch {}
191	        const reply = (payload) => res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify(payload));
192	        const action = { tool: match[1], args, at: Date.now() };
193	        emitter('game:action', action);
194	        try {
195	          const result = await runTool(match[1], args);
196	          emitter('game:action', { ...action, result, done: Date.now() });
197	          reply({ ok: true, result });
198	        } catch (e) {
199	          emitter('game:action', { ...action, error: e.message, done: Date.now() });
200	          reply({ ok: false, error: e.message });
201	        }
202	      });
203	    });
204	    control.listen(0, '127.0.0.1', () => {
205	      setState({ controlUrl: `http://127.0.0.1:${control.address().port}` });
206	      resolve();
207	    });
208	  });
209	}
