273	async function swapPlugin(jarPath) {
274	  if (!fs.existsSync(jarPath)) return { loaded: false, plugin: null, errors: [`Jar not found: ${jarPath}`], logTail: [] };
275	  if (mock()) return { loaded: true, plugin: path.basename(jarPath, '.jar'), errors: [], logTail: ['[mock] plugin enabled'] };
276	  systemNode();
277	  await startControl();
278	  await stopHost();
279	  await server.stop();
280	  setState({ server: 'stopped', bot: 'offline', viewerUrl: null });
281	  const dir = server.pluginsDir();
282	  fs.mkdirSync(dir, { recursive: true });
283	  for (const f of fs.readdirSync(dir)) if (/^studio-.*\.jar$/.test(f)) fs.rmSync(path.join(dir, f));
284	  fs.copyFileSync(jarPath, path.join(dir, `studio-${path.basename(jarPath)}`));
285	  const since = Date.now();
286	  await bootGame();
287	  const lines = server.logSince(since);
288	  const enabled = lines.map((l) => l.line.match(/\[([^\]]+)\] Enabling (\S+) v/)).find(Boolean);
289	  const errors = lines.filter((l) => l.level === 'error').map((l) => l.line);
290	  return { loaded: Boolean(enabled), plugin: enabled ? enabled[2] : null, errors, logTail: lines.slice(-40).map((l) => l.line) };
291	}
