334	// With a test plan, any check the playtester never reported counts as blocked, so a partial run can't pass.
335	function readVerdict(verdictFile, testPlan) {
336	  let v;
337	  try { v = JSON.parse(fs.readFileSync(verdictFile, 'utf8')); }
338	  catch (e) { return { version: 1, finished: false, passed: false, checks: [], serverErrors: [], error: `No verdict: ${e.message}` }; }
339	  const reported = Array.isArray(v.checks) ? v.checks : [];
340	  const finished = v.finished === true;
341	  const missing = (testPlan?.checks || []).filter((c) => !reported.some((r) => r.id === c.id))
342	    .map((c) => ({ id: c.id, status: 'blocked', expected: c.expect, observed: finished ? 'The playtester finished without reporting this check.' : 'Not reported yet.', evidence: {} }));
343	  const checks = [...reported, ...missing];
344	  const serverErrors = Array.isArray(v.serverErrors) ? v.serverErrors : [];
345	  return { ...v, checks, serverErrors, finished, passed: finished && checks.length > 0 && checks.every((c) => c.status === 'pass') && serverErrors.length === 0 };
346	}
347	
348	function mockVerdict(testPlan, attempt) {
349	  const checks = (testPlan.checks || []).map((c, i) => {
350	    const failing = attempt <= 1 && i === 0;
351	    return {
352	      id: c.id,
353	      status: failing ? 'fail' : 'pass',
354	      expected: c.expect,
355	      observed: failing ? '[mock] max upward velocity 0.0; mob took damage but stayed grounded' : '[mock] matched expectation',
356	      evidence: { samples: [], serverLog: [] },
357	      ...(failing ? { suspectedCause: '[mock] velocity is overwritten by knockback after the damage event' } : {}),
358	    };
359	  });
360	  return { version: 1, runId: `mock_${attempt}`, finished: true, passed: checks.every((c) => c.status === 'pass'), summary: '[mock verdict]', checks, serverErrors: [] };
361	}
