363	// Attract mode for recordings: summon a husk in front of the bot and hit it, on repeat.
364	let demoTimer = null;
365	async function demoHit() {
366	  await runTool('game_setup', { commands: ['kill @e[type=husk]', 'give @bot golden_sword', 'summon husk ^ ^ ^3 {PersistenceRequired:1b}'] });
367	  await runTool('wait_ticks', { ticks: 25 });
368	  await runTool('equip', { item: 'golden_sword' });
369	  const husk = (await runTool('nearby_entities', { radius: 8 })).find((e) => e.name === 'husk');
370	  return husk ? runTool('attack', { entityId: husk.id, trackTicks: 30 }) : null;
371	}
372	
373	function demo(on) {
374	  clearInterval(demoTimer);
375	  demoTimer = null;
376	  if (!on) return { demo: false };
377	  let busy = false;
378	  const tick = () => {
379	    if (busy || state.bot !== 'online') return;
380	    busy = true;
381	    demoHit().catch(() => {}).finally(() => { busy = false; });
382	  };
383	  demoTimer = setInterval(tick, 7000);
384	  tick();
385	  return { demo: true };
386	}
387	
388	function handlers(emit) {
389	  emitter = emit;
390	  if (process.env.BENANA_GAME_AUTOSTART === '1' && !mock()) {
391	    setTimeout(() => start(emit).then(() => process.env.BENANA_GAME_DEMO === '1' && demo(true)).catch(() => {}), 2000);
392	  }
393	  return {
394	    'game:demo': ({ on }) => demo(on),
395	    'game:status': () => status(),
396	    'game:logs': ({ limit } = {}) => server.logSince(0).slice(-Math.min(Number(limit) || 300, 1000)),
397	    'game:start': () => start(emit),
398	    'game:stop': () => stop(),
399	    'game:command': ({ command }) => runCommand(command),
400	    'game:tool': ({ tool, args }) => runTool(tool, args),
401	  };
402	}
403	
404	module.exports = {
405	  VERSION, status, start, stop, deployPlugin, runCommand, runTool,
406	  mcpConfig, playtesterTools, playtestPrompt, readVerdict, mockVerdict, handlers,
407	};
