88	  for (const l of lines) {
89	    const frame = /^\s*(at |Caused by|\.\.\. \d+ more)/.test(l.line);
90	    if (frame && out.length) out[out.length - 1].stack += `${l.line}\n`;
91	    else out.push({ at: l.at, message: l.line, stack: '' });
