104	  if (name === 'report_check') {
105	    const v = readVerdict();
106	    const check = { id: a.id, status: a.status, expected: a.expected, observed: a.observed, evidence: a.evidence || {}, ...(a.suspectedCause ? { suspectedCause: a.suspectedCause } : {}) };
107	    v.checks = [...v.checks.filter((c) => c.id !== a.id), check];
